export const SUFFIX_LIST = ['!', '?', '!!', '!?', '?!', '??'] as const

export type Suffix = (typeof SUFFIX_LIST)[number]

// NAG (Numeric Annotation Glyph) to symbol mapping
/* eslint-disable @typescript-eslint/naming-convention */
export const NAG_TO_SYMBOL = {
  7: '□', // Only move
  22: '⨀', // Zugzwang
  10: '=', // Equal position
  13: '∞', // Unclear position
  14: '⩲', // White is slightly better
  15: '⩱', // Black is slightly better
  16: '±', // White is better
  17: '∓', // Black is better
  18: '+−', // White is winning
  19: '-+', // Black is winning
  146: 'N', // Novelty
  32: '↑↑', // Development
  36: '↑', // Initiative
  40: '→', // Attack
  132: '⇆', // Counterplay
  138: '⊕', // Time trouble
  44: '=∞', // With compensation
  140: '∆', // With the idea
} as const
/* eslint-enable @typescript-eslint/naming-convention */

export type NAG = number

/**
 * Convert a NAG (Numeric Annotation Glyph) to its text symbol representation.
 * Returns undefined if the NAG has no corresponding symbol.
 */
export function nagToGlyph(nag: NAG): string | undefined {
  return NAG_TO_SYMBOL[nag as keyof typeof NAG_TO_SYMBOL]
}

export const DEFAULT_POSITION =
  'rnbqkbnr/pppppppp/8/8/8/8/PPPPPPPP/RNBQKBNR w KQkq - 0 1'

export type Piece = {
  color: Color
  type: PieceSymbol
}

type InternalMove = {
  color: Color
  from: number
  to: number
  piece: PieceSymbol
  captured?: PieceSymbol
  promotion?: PieceSymbol
  flags: number
}

interface History {
  move: InternalMove
  kings: Record<Color, number>
  turn: Color
  castling: Record<Color, number>
  epSquare: number
  fenEpSquare: number
  halfMoves: number
  moveNumber: number
}

export class Move {
  color: Color
  from: Square
  to: Square
  piece: PieceSymbol
  captured?: PieceSymbol
  promotion?: PieceSymbol

  /**
   * @deprecated This field is deprecated and will be removed in version 2.0.0.
   * Please use move descriptor functions instead: `isCapture`, `isPromotion`,
   * `isEnPassant`, `isKingsideCastle`, `isQueensideCastle`, `isCastle`,
   * `isBigPawn`, and `isCheck`
   */
  flags: string

  san: string
  lan: string
  before: string
  after: string

  constructor(
    internal: InternalMove,
    san: string,
    before: string,
    after: string,
  ) {
    const { color, piece, from, to, flags, captured, promotion } = internal

    const fromAlgebraic = algebraic(from)
    const toAlgebraic = algebraic(to)

    this.color = color
    this.piece = piece
    this.from = fromAlgebraic
    this.to = toAlgebraic

    this.san = san
    this.lan = fromAlgebraic + toAlgebraic
    this.before = before
    this.after = after

    // Build the text representation of the move flags
    this.flags = ''
    for (const flag in BITS) {
      if (BITS[flag] & flags) {
        this.flags += FLAGS[flag]
      }
    }

    if (captured) {
      this.captured = captured
    }

    if (promotion) {
      this.promotion = promotion
      this.lan += promotion
    }
  }

  isCapture() {
    return this.flags.indexOf(FLAGS['CAPTURE']) > -1
  }

  isPromotion() {
    return this.flags.indexOf(FLAGS['PROMOTION']) > -1
  }

  isEnPassant() {
    return this.flags.indexOf(FLAGS['EP_CAPTURE']) > -1
  }

  isKingsideCastle() {
    return this.flags.indexOf(FLAGS['KSIDE_CASTLE']) > -1
  }

  isQueensideCastle() {
    return this.flags.indexOf(FLAGS['QSIDE_CASTLE']) > -1
  }

  isBigPawn() {
    return this.flags.indexOf(FLAGS['BIG_PAWN']) > -1
  }

  isNullMove() {
    return this.flags.indexOf(FLAGS['NULL_MOVE']) > -1
  }

  isCheck() {
    return this.san.includes('+') || this.san.includes('#')
  }
}

const EMPTY = -1

const FLAGS: Record<string, string> = {
  NORMAL: 'n',
  CAPTURE: 'c',
